   !> symmetric or LU)
   subroutine dpcm_original_point_assemble(state, r, n, k1, k2, a, error, solver)
      !> State of dpcm_original_point
      type(dpcm_original_point_state), target, intent(inout) :: state
      !> Positions of the surface points
      real(wp), contiguous, intent(in) :: r(:, :)
      !> Outward unit normals at the surface points
      real(wp), contiguous, intent(in) :: n(:, :)
      !> First principal curvature (positive where convex)
      real(wp), contiguous, intent(in) :: k1(:)
      !> Second principal curvature (positive where convex)
      real(wp), contiguous, intent(in) :: k2(:)
      !> Grid point areas
      real(wp), contiguous, intent(in) :: a(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error
      !> Linear solver
      class(pcm_solver), intent(in), optional :: solver

      integer :: npt
      integer :: stat
      real(wp) :: tmp1, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35
      integer :: i, j

      if (present(solver)) then
         if (solver%matrix_free(size(r, 2), 1)) then
            call dpcm_original_point_mf_assemble(state, r, n, k1, k2, a, error, solver)
            return
         end if
      end if
      stat = 0
      npt = size(r, 2)
      if (npt < 1) then
         call fatal_error(error, "[dpcm_original_point_assemble] empty discretization")
         return
      end if
      if (any(shape(r) /= [3, npt])) then
         call fatal_error(error, "[dpcm_original_point_assemble] r: wrong shape")
         return
      end if
      if (any(shape(n) /= [3, npt])) then
         call fatal_error(error, "[dpcm_original_point_assemble] n: wrong shape")
         return
      end if
      if (any(shape(k1) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_assemble] k1: wrong shape")
         return
      end if
      if (any(shape(k2) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_assemble] k2: wrong shape")
         return
      end if
      if (any(shape(a) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_assemble] a: wrong shape")
         return
      end if
      state%ready = 0
      if (allocated(state%solver)) deallocate (state%solver)
      if (allocated(state%a)) deallocate (state%a)
      if (allocated(state%s5)) deallocate (state%s5)
      if (allocated(state%s6)) deallocate (state%s6)
      if (allocated(state%r)) deallocate (state%r)
      if (allocated(state%s7)) deallocate (state%s7)
      if (allocated(state%s8)) deallocate (state%s8)
      if (allocated(state%s9)) deallocate (state%s9)
      if (allocated(state%s10)) deallocate (state%s10)
      if (allocated(state%s11)) deallocate (state%s11)
      if (allocated(state%k1)) deallocate (state%k1)
      if (allocated(state%k2)) deallocate (state%k2)
      if (allocated(state%s12)) deallocate (state%s12)
      if (allocated(state%s13)) deallocate (state%s13)
      if (allocated(state%s14)) deallocate (state%s14)
      if (allocated(state%s15)) deallocate (state%s15)
      if (allocated(state%s16)) deallocate (state%s16)
      if (allocated(state%s17)) deallocate (state%s17)
      if (allocated(state%s18)) deallocate (state%s18)
      if (allocated(state%s20)) deallocate (state%s20)
      if (allocated(state%s21)) deallocate (state%s21)
      if (allocated(state%s22)) deallocate (state%s22)
      if (allocated(state%n)) deallocate (state%n)
      state%npt = npt
      if (present(solver)) then
         allocate (state%solver, source=solver, stat=stat)
      else
         allocate (pcm_dense_solver :: state%solver, stat=stat)
      end if
      if (stat == 0) allocate (state%a(npt), stat=stat)
      if (stat == 0) allocate (state%s5(npt), stat=stat)
      if (stat == 0) allocate (state%s6(npt), stat=stat)
      if (stat == 0) allocate (state%r(3, npt), stat=stat)
      if (stat == 0) allocate (state%s7(npt), stat=stat)
      if (stat == 0) allocate (state%s8(npt), stat=stat)
      if (stat == 0) allocate (state%s9(npt), stat=stat)
      if (stat == 0) allocate (state%s10(npt), stat=stat)
      if (stat == 0) allocate (state%s11(npt), stat=stat)
      if (stat == 0) allocate (state%k1(npt), stat=stat)
      if (stat == 0) allocate (state%k2(npt), stat=stat)
      if (stat == 0) allocate (state%s12(npt, npt), stat=stat)
      if (stat == 0) allocate (state%s13(npt), stat=stat)
      if (stat == 0) allocate (state%s14(npt), stat=stat)
      if (stat == 0) allocate (state%s15(npt), stat=stat)
      if (stat == 0) allocate (state%s16(npt), stat=stat)
      if (stat == 0) allocate (state%s17(npt), stat=stat)
      if (stat == 0) allocate (state%s18(npt), stat=stat)
      if (stat == 0) allocate (state%s20(npt), stat=stat)
      if (stat == 0) allocate (state%s21(npt), stat=stat)
      if (stat == 0) allocate (state%s22(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_assemble] allocation failed")
         return
      end if
      state%s13 = 0.0_wp
      state%s14 = 0.0_wp
      call state%solver%reset(dpcm_original_point_n_operators)
      state%matrix_free = .false.

      state%a = a
      state%r = r
      state%k1 = k1
      state%k2 = k2
      do i = 1, npt
         tmp1 = 1.0_wp/state%a(i)
         state%s5(i) = tmp1
      end do
      state%s6 = n(1, :)
      state%s7 = state%r(1, :)
      state%s8 = state%r(2, :)
      state%s9 = n(2, :)
      state%s10 = state%r(3, :)
      state%s11 = n(3, :)
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(npt, state)
      do j = 1, npt
         block
            real(wp) :: tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, &
                        tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp21, tmp22, &
                        tmp23, tmp24, tmp25, tmp26, tmp27, tmp28, tmp29

            do i = 1, j - 1
               tmp2 = -state%s7(j)
               tmp3 = state%s7(i) + tmp2
               tmp4 = state%s6(j)*tmp3
               tmp5 = -state%s8(j)
               tmp6 = state%s8(i) + tmp5
               tmp7 = tmp6*state%s9(j)
               tmp8 = tmp4 + tmp7
               tmp9 = -state%s10(j)
               tmp10 = state%s10(i) + tmp9
               tmp11 = tmp10*state%s11(j)
               tmp12 = tmp8 + tmp11
               tmp13 = tmp3**(2)
               tmp14 = tmp6**(2)
               tmp15 = tmp13 + tmp14
               tmp16 = tmp10**(2)
               tmp17 = tmp15 + tmp16
               tmp18 = 1.0_wp/sqrt(tmp17)
               tmp19 = tmp18**(3)
               tmp20 = tmp12*tmp19
               state%s12(i, j) = tmp20
               tmp21 = -tmp3
               tmp22 = state%s6(i)*tmp21
               tmp23 = -tmp6
               tmp24 = tmp23*state%s9(i)
               tmp25 = tmp22 + tmp24
               tmp26 = -tmp10
               tmp27 = tmp26*state%s11(i)
               tmp28 = tmp25 + tmp27
               tmp29 = tmp28*tmp19
               state%s12(j, i) = tmp29
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         tmp30 = state%k1(i) + state%k2(i)
         tmp31 = 1.0_wp/state%a(i)
         tmp32 = 12.566370614359172_wp*tmp31
         tmp33 = sqrt(tmp32)
         tmp34 = tmp30*tmp33
         tmp35 = (-0.26735_wp)*tmp34
         state%s12(i, i) = tmp35
      end do

      state%ready = 1
      state%assembled = state%assembled + 1
   end subroutine dpcm_original_point_assemble

   !> DPCM, original form (point charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs dpcm_original_point_assemble on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_medium(state, eps, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      real(wp), intent(in) :: eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1, tmp2

      if (state%matrix_free) then
         call dpcm_original_point_mf_medium(state, eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, &
                          "[dpcm_original_point_medium] call dpcm_original_point_assemble first")
         return
      end if
      state%ready = 1
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op1%npt = npt
      state%op1%npoint = npt
      state%op1%id = 1
      state%op1%points => state%r
      state%s1 = eps + 1.0_wp
      tmp1 = 1.0_wp/state%s1
      tmp2 = (-2.0_wp)*tmp1
      state%s2 = 1.0_wp + tmp2
      state%s3 = 1.0_wp/state%s2
      state%s4 = 6.283185307179586_wp*state%s3
      state%op1%c1 = state%s4
      state%op1%c2 => state%s5
      state%op1%c3 => state%s12
      call state%solver%setup(state%op1, error)
      if (allocated(error)) return

      state%ready = 2
   end subroutine dpcm_original_point_medium

   !> DPCM, original form (point charges): energy, solution and gradient for v, vn
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs dpcm_original_point_medium on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[in] vn  outward normal derivative of the solute potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] grad_vn  partial derivative of the energy with respect to vn
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_solve(state, v, vn, energy, q, grad_v, grad_vn, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      real(wp), contiguous, intent(in) :: v(:)
      !> Outward normal derivative of the solute potential at the surface points
      real(wp), contiguous, intent(in) :: vn(:)
      !> Solvation energy
      real(wp), intent(out) :: energy
      !> Apparent surface charges
      real(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      real(wp), contiguous, intent(out) :: grad_v(:)
      !> Partial derivative of the energy with respect to vn
      real(wp), contiguous, intent(out) :: grad_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp6(:), tmp7(:), tmp8(:)
      real(wp) :: tmp1, tmp9

      if (state%matrix_free) then
         call dpcm_original_point_mf_solve(state, v, vn, energy, q, grad_v, grad_vn, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 2) then
         call fatal_error(error, &
                          "[dpcm_original_point_solve] call dpcm_original_point_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_solve] v: wrong shape")
         return
      end if
      if (any(shape(vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_solve] vn: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_solve] grad_v: wrong shape")
         return
      end if
      if (any(shape(grad_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_solve] grad_vn: wrong shape")
         return
      end if
      allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_solve] allocation failed")
         return
      end if
      state%ready = 2

      state%op1%points => state%r
      state%op1%c2 => state%s5
      state%op1%c3 => state%s12
      call state%solver%solve(state%op1, .false., vn, state%s13, error)
      if (allocated(error)) return
      call state%solver%solve(state%op1, .true., v, state%s14, error)
      if (allocated(error)) return
      state%s15 = 0.5_wp*state%s14
      tmp1 = dot(v, state%s13)
      energy = 0.5_wp*tmp1
      q = state%s13
      grad_v = 0.5_wp*state%s13
      grad_vn = state%s15
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         tmp2 = state%s5*state%s13
         tmp3 = state%s4*tmp2
         call gemv(state%s12, state%s13, tmp4, trans="t")
         tmp5 = -tmp4
         tmp6 = tmp3 + tmp5
         tmp7 = -tmp6
         tmp8 = vn + tmp7
         tmp9 = dot(state%s15, tmp8)
         energy = energy + tmp9
      end if

      state%ready = 3
   end subroutine dpcm_original_point_solve

   !> DPCM, original form (point charges): energy gradient with respect to the other inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs dpcm_original_point_solve on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[out] grad_r  partial derivative of the energy with respect to r
   !> @param[out] grad_n  partial derivative of the energy with respect to n
   !> @param[out] grad_k1  partial derivative of the energy with respect to k1
   !> @param[out] grad_k2  partial derivative of the energy with respect to k2
   !> @param[out] grad_a  partial derivative of the energy with respect to a
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, &
                                          grad_eps, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to r
      real(wp), contiguous, intent(out) :: grad_r(:, :)
      !> Partial derivative of the energy with respect to n
      real(wp), contiguous, intent(out) :: grad_n(:, :)
      !> Partial derivative of the energy with respect to k1
      real(wp), contiguous, intent(out) :: grad_k1(:)
      !> Partial derivative of the energy with respect to k2
      real(wp), contiguous, intent(out) :: grad_k2(:)
      !> Partial derivative of the energy with respect to a
      real(wp), contiguous, intent(out) :: grad_a(:)
      !> Partial derivative of the energy with respect to eps
      real(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp15(:), tmp16(:), tmp17(:), tmp18(:), tmp19(:), tmp20(:), &
                               tmp87(:), tmp88(:), tmp89(:), tmp90(:)
      real(wp) :: tmp1, tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, &
                  tmp13, tmp14, tmp91, tmp92, tmp93, tmp94, tmp95
      integer :: i, j

      if (state%matrix_free) then
         call dpcm_original_point_mf_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, &
                                             grad_eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 3) then
         call fatal_error(error, &
                          "[dpcm_original_point_weights] call dpcm_original_point_solve first")
         return
      end if
      if (any(shape(grad_r) /= [3, npt])) then
         call fatal_error(error, "[dpcm_original_point_weights] grad_r: wrong shape")
         return
      end if
      if (any(shape(grad_n) /= [3, npt])) then
         call fatal_error(error, "[dpcm_original_point_weights] grad_n: wrong shape")
         return
      end if
      if (any(shape(grad_k1) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_weights] grad_k1: wrong shape")
         return
      end if
      if (any(shape(grad_k2) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_weights] grad_k2: wrong shape")
         return
      end if
      if (any(shape(grad_a) /= [npt])) then
         call fatal_error(error, "[dpcm_original_point_weights] grad_a: wrong shape")
         return
      end if
      allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp20(npt), stat=stat)
      if (stat == 0) allocate (tmp87(npt), stat=stat)
      if (stat == 0) allocate (tmp88(npt), stat=stat)
      if (stat == 0) allocate (tmp89(npt), stat=stat)
      if (stat == 0) allocate (tmp90(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_weights] allocation failed")
         return
      end if
      state%ready = 3

      state%op1%points => state%r
      state%op1%c2 => state%s5
      state%op1%c3 => state%s12
      state%s16 = state%s13*state%s15
      do i = 1, npt
         tmp1 = 1.0_wp/state%a(i)
         tmp2 = 12.566370614359172_wp*tmp1
         tmp3 = sqrt(tmp2)
         tmp4 = (-0.26735_wp)*tmp3
         state%s17(i) = tmp4
      end do
      do i = 1, npt
         tmp5 = 1.0_wp/state%a(i)
         tmp6 = 12.566370614359172_wp*tmp5
         tmp7 = 1.0_wp/sqrt(tmp6)
         tmp8 = state%k1(i) + state%k2(i)
         tmp9 = tmp7*tmp8
         tmp10 = state%a(i)**(-2)
         tmp11 = tmp9*tmp10
         tmp12 = 1.6798095918744622_wp*tmp11
         state%s18(i) = tmp12
      end do
      state%s19 = (-3.141592653589793_wp)*state%s3
      state%s20 = state%s19*state%s14
      state%s21 = state%s20*state%s13
      do i = 1, npt
         tmp13 = state%a(i)**(-2)
         tmp14 = -tmp13
         state%s22(i) = tmp14
      end do
      tmp15 = 0.0_wp
      tmp16 = 0.0_wp
      tmp17 = 0.0_wp
      tmp18 = 0.0_wp
      tmp19 = 0.0_wp
      tmp20 = 0.0_wp
      !$omp parallel default(none) &
      !$omp& private(i, j) &
      !$omp& shared(npt, state, tmp18, tmp19, tmp20) &
      !$omp& reduction(+: tmp15, tmp16, tmp17)
      block
         real(wp) :: tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp38, tmp42, &
                     tmp21, tmp22, tmp23, tmp24, tmp25, tmp26

         !$omp do schedule(static)
         do j = 1, npt
            tmp27 = state%s6(j)
            tmp28 = state%s7(j)
            tmp29 = state%s8(j)
            tmp30 = state%s9(j)
            tmp31 = state%s10(j)
            tmp32 = state%s11(j)
            tmp33 = state%s15(j)
            tmp34 = state%s13(j)
            tmp35 = -tmp28
            tmp38 = -tmp29
            tmp42 = -tmp31
            tmp21 = 0.0_wp
            tmp22 = 0.0_wp
            tmp23 = 0.0_wp
            tmp24 = 0.0_wp
            tmp25 = 0.0_wp
            tmp26 = 0.0_wp
            !$omp simd &
            !$omp& reduction(+: tmp21, tmp22, tmp23, tmp24, tmp25, tmp26)
            do i = 1, j - 1
               block
                  real(wp) :: tmp36, tmp37, tmp39, tmp40, tmp41, tmp43, tmp44, tmp45, tmp46, &
                              tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, tmp55, &
                              tmp56, tmp57, tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, &
                              tmp65, tmp66, tmp67, tmp68, tmp69, tmp70, tmp71, tmp72, tmp73, &
                              tmp74, tmp75, tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, tmp82, &
                              tmp83, tmp84, tmp85, tmp86

                  tmp36 = state%s7(i) + tmp35
                  tmp37 = tmp27*tmp36
                  tmp39 = state%s8(i) + tmp38
                  tmp40 = tmp39*tmp30
                  tmp41 = tmp37 + tmp40
                  tmp43 = state%s10(i) + tmp42
                  tmp44 = tmp43*tmp32
                  tmp45 = tmp41 + tmp44
                  tmp46 = tmp45*tmp36
                  tmp47 = tmp36**(2)
                  tmp48 = tmp39**(2)
                  tmp49 = tmp47 + tmp48
                  tmp50 = tmp43**(2)
                  tmp51 = tmp49 + tmp50
                  tmp52 = 1.0_wp/sqrt(tmp51)
                  tmp53 = tmp52**(5)
                  tmp54 = tmp46*tmp53
                  tmp55 = (-3.0_wp)*tmp54
                  tmp56 = tmp52**(3)
                  tmp57 = tmp27*tmp56
                  tmp58 = tmp55 + tmp57
                  tmp59 = tmp58*tmp33
                  tmp60 = tmp59*state%s13(i)
                  tmp15(i) = tmp15(i) + tmp60
                  tmp61 = -tmp60
                  tmp21 = tmp21 + tmp61
                  tmp62 = tmp39*tmp45
                  tmp63 = tmp62*tmp53
                  tmp64 = (-3.0_wp)*tmp63
                  tmp65 = tmp30*tmp56
                  tmp66 = tmp64 + tmp65
                  tmp67 = tmp66*tmp33
                  tmp68 = tmp67*state%s13(i)
                  tmp16(i) = tmp16(i) + tmp68
                  tmp69 = -tmp68
                  tmp22 = tmp22 + tmp69
                  tmp70 = tmp43*tmp45
                  tmp71 = tmp70*tmp53
                  tmp72 = (-3.0_wp)*tmp71
                  tmp73 = tmp32*tmp56
                  tmp74 = tmp72 + tmp73
                  tmp75 = tmp74*tmp33
                  tmp76 = tmp75*state%s13(i)
                  tmp17(i) = tmp17(i) + tmp76
                  tmp77 = -tmp76
                  tmp23 = tmp23 + tmp77
                  tmp78 = tmp56*tmp36
                  tmp79 = tmp78*tmp33
                  tmp80 = tmp79*state%s13(i)
                  tmp24 = tmp24 + tmp80
                  tmp81 = tmp39*tmp56
                  tmp82 = tmp81*tmp33
                  tmp83 = tmp82*state%s13(i)
                  tmp25 = tmp25 + tmp83
                  tmp84 = tmp43*tmp56
                  tmp85 = tmp84*tmp33
                  tmp86 = tmp85*state%s13(i)
                  tmp26 = tmp26 + tmp86
               end block
            end do
            !$omp simd &
            !$omp& reduction(+: tmp21, tmp22, tmp23, tmp24, tmp25, tmp26)
            do i = j + 1, npt
               block
                  real(wp) :: tmp36, tmp37, tmp39, tmp40, tmp41, tmp43, tmp44, tmp45, tmp46, &
                              tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, tmp55, &
                              tmp56, tmp57, tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, &
                              tmp65, tmp66, tmp67, tmp68, tmp69, tmp70, tmp71, tmp72, tmp73, &
                              tmp74, tmp75, tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, tmp82, &
                              tmp83, tmp84, tmp85, tmp86

                  tmp36 = state%s7(i) + tmp35
                  tmp37 = tmp27*tmp36
                  tmp39 = state%s8(i) + tmp38
                  tmp40 = tmp39*tmp30
                  tmp41 = tmp37 + tmp40
                  tmp43 = state%s10(i) + tmp42
                  tmp44 = tmp43*tmp32
                  tmp45 = tmp41 + tmp44
                  tmp46 = tmp45*tmp36
                  tmp47 = tmp36**(2)
                  tmp48 = tmp39**(2)
                  tmp49 = tmp47 + tmp48
                  tmp50 = tmp43**(2)
                  tmp51 = tmp49 + tmp50
                  tmp52 = 1.0_wp/sqrt(tmp51)
                  tmp53 = tmp52**(5)
                  tmp54 = tmp46*tmp53
                  tmp55 = (-3.0_wp)*tmp54
                  tmp56 = tmp52**(3)
                  tmp57 = tmp27*tmp56
                  tmp58 = tmp55 + tmp57
                  tmp59 = tmp58*tmp33
                  tmp60 = tmp59*state%s13(i)
                  tmp15(i) = tmp15(i) + tmp60
                  tmp61 = -tmp60
                  tmp21 = tmp21 + tmp61
                  tmp62 = tmp39*tmp45
                  tmp63 = tmp62*tmp53
                  tmp64 = (-3.0_wp)*tmp63
                  tmp65 = tmp30*tmp56
                  tmp66 = tmp64 + tmp65
                  tmp67 = tmp66*tmp33
                  tmp68 = tmp67*state%s13(i)
                  tmp16(i) = tmp16(i) + tmp68
                  tmp69 = -tmp68
                  tmp22 = tmp22 + tmp69
                  tmp70 = tmp43*tmp45
                  tmp71 = tmp70*tmp53
                  tmp72 = (-3.0_wp)*tmp71
                  tmp73 = tmp32*tmp56
                  tmp74 = tmp72 + tmp73
                  tmp75 = tmp74*tmp33
                  tmp76 = tmp75*state%s13(i)
                  tmp17(i) = tmp17(i) + tmp76
                  tmp77 = -tmp76
                  tmp23 = tmp23 + tmp77
                  tmp78 = tmp56*tmp36
                  tmp79 = tmp78*tmp33
                  tmp80 = tmp79*state%s13(i)
                  tmp24 = tmp24 + tmp80
                  tmp81 = tmp39*tmp56
                  tmp82 = tmp81*tmp33
                  tmp83 = tmp82*state%s13(i)
                  tmp25 = tmp25 + tmp83
                  tmp84 = tmp43*tmp56
                  tmp85 = tmp84*tmp33
                  tmp86 = tmp85*state%s13(i)
                  tmp26 = tmp26 + tmp86
               end block
            end do
            tmp15(j) = tmp15(j) + tmp21
            tmp16(j) = tmp16(j) + tmp22
            tmp17(j) = tmp17(j) + tmp23
            tmp18(j) = tmp18(j) + tmp24
            tmp19(j) = tmp19(j) + tmp25
            tmp20(j) = tmp20(j) + tmp26
         end do
         !$omp end do
      end block
      !$omp end parallel
      grad_r(1, :) = tmp15
      grad_r(2, :) = tmp16
      grad_r(3, :) = tmp17
      grad_n(1, :) = tmp18
      grad_n(2, :) = tmp19
      grad_n(3, :) = tmp20
      grad_k1 = state%s16*state%s17
      grad_k2 = grad_k1
      tmp87 = state%s16*state%s18
      tmp88 = state%s21*state%s22
      grad_a = tmp87 + tmp88
      tmp89 = (-0.5_wp)*state%s14
      tmp90 = state%s5*state%s13
      tmp91 = dot(tmp89, tmp90)
      tmp92 = state%s2**(-2)
      tmp93 = tmp91*tmp92
      tmp94 = state%s1**(-2)
      tmp95 = tmp93*tmp94
      grad_eps = (-12.566370614359172_wp)*tmp95

      state%ready = 4
   end subroutine dpcm_original_point_weights

   !> DPCM, original form (point charges): gradient tangents along blocks of directions
   !>
   !> - Directions of the cavity and QM inputs; for the inputs of the last solve
   !> - Needs dpcm_original_point_weights on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] dr  direction for r
   !> @param[in] dn  direction for n
   !> @param[in] dk1  direction for k1
   !> @param[in] dk2  direction for k2
   !> @param[in] da  direction for a
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_r  hessian times direction, r block
   !> @param[out] hvp_n  hessian times direction, n block
   !> @param[out] hvp_k1  hessian times direction, k1 block
   !> @param[out] hvp_k2  hessian times direction, k2 block
   !> @param[out] hvp_a  hessian times direction, a block
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_point_tangent(state, dr, dn, dk1, dk2, da, dv, dvn, hvp_r, hvp_n, &
                                          hvp_k1, hvp_k2, hvp_a, hvp_v, hvp_vn, error)
      !> State of dpcm_original_point
      type(dpcm_original_point_state), intent(inout) :: state
      !> Direction for r
      real(wp), contiguous, intent(in) :: dr(:, :, :)
      !> Direction for n
      real(wp), contiguous, intent(in) :: dn(:, :, :)
      !> Direction for k1
      real(wp), contiguous, intent(in) :: dk1(:, :)
      !> Direction for k2
      real(wp), contiguous, intent(in) :: dk2(:, :)
      !> Direction for a
      real(wp), contiguous, intent(in) :: da(:, :)
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, r block
      real(wp), contiguous, intent(out) :: hvp_r(:, :, :)
      !> Hessian times direction, n block
      real(wp), contiguous, intent(out) :: hvp_n(:, :, :)
      !> Hessian times direction, k1 block
      real(wp), contiguous, intent(out) :: hvp_k1(:, :)
      !> Hessian times direction, k2 block
      real(wp), contiguous, intent(out) :: hvp_k2(:, :)
      !> Hessian times direction, a block
      real(wp), contiguous, intent(out) :: hvp_a(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call dpcm_original_point_mf_tangent(state, dr, dn, dk1, dk2, da, dv, dvn, hvp_r, hvp_n, &
                                             hvp_k1, hvp_k2, hvp_a, hvp_v, hvp_vn, error)
         return
      end if
      if (state%ready < 4) then
         call fatal_error(error, &
                          "[dpcm_original_point_tangent] call dpcm_original_point_weights first")
         return
      end if
      npt = state%npt
      nblk = size(dr, 3)
      if (any(shape(dr) /= [3, npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] dr: wrong shape")
         return
      end if
      if (any(shape(dn) /= [3, npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] dn: wrong shape")
         return
      end if
      if (any(shape(dk1) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] dk1: wrong shape")
         return
      end if
      if (any(shape(dk2) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] dk2: wrong shape")
         return
      end if
      if (any(shape(da) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] da: wrong shape")
         return
      end if
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_r) /= [3, npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] hvp_r: wrong shape")
         return
      end if
      if (any(shape(hvp_n) /= [3, npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] hvp_n: wrong shape")
         return
      end if
      if (any(shape(hvp_k1) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] hvp_k1: wrong shape")
         return
      end if
      if (any(shape(hvp_k2) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] hvp_k2: wrong shape")
         return
      end if
      if (any(shape(hvp_a) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] hvp_a: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_point_tangent] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call dpcm_original_point_tangent_one(state, dr(:, :, blk), dn(:, :, blk), dk1(:, blk), &
                                              dk2(:, blk), da(:, blk), dv(:, blk), dvn(:, blk), &
                                              hvp_r(:, :, blk), hvp_n(:, :, blk), hvp_k1(:, blk), &
                                              hvp_k2(:, blk), hvp_a(:, blk), hvp_v(:, blk), &
                                              hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine dpcm_original_point_tangent

   !> One direction of dpcm_original_point_tangent
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original_point
   !> @param[in] dr  direction for r
   !> @param[in] dn  direction for n
   !> @param[in] dk1  direction for k1
   !> @param[in] dk2  direction for k2
   !> @param[in] da  direction for a
   !> @param[in] dv  direction for v
