   !> Apply operator 3 or its transpose (not conjugated)
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine dpcm_original_point_op3_apply(self, trans, x, y)
      !> Operator
      class(dpcm_original_point_op3), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      complex(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      complex(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         block
            real(wp) :: tmp4(self%npt), tmp5(self%npt)
            complex(wp) :: tmp1(self%npt), tmp2(self%npt), tmp3(self%npt), tmp6(self%npt)

            tmp1 = self%c2*x
            tmp2 = self%c1*tmp1
            call gemv(self%c3, real(x, wp), tmp4)
            call gemv(self%c3, aimag(x), tmp5)
            tmp3 = cmplx(tmp4, tmp5, wp)
            tmp6 = -tmp3
            y = tmp2 + tmp6
         end block
      else
         block
            real(wp) :: tmp4(self%npt), tmp5(self%npt)
            complex(wp) :: tmp1(self%npt), tmp2(self%npt), tmp3(self%npt), tmp6(self%npt)

            tmp1 = self%c2*x
            tmp2 = self%c1*tmp1
            call gemv(self%c3, real(x, wp), tmp4, trans="t")
            call gemv(self%c3, aimag(x), tmp5, trans="t")
            tmp3 = cmplx(tmp4, tmp5, wp)
            tmp6 = -tmp3
            y = tmp2 + tmp6
         end block
      end if
   end subroutine dpcm_original_point_op3_apply

   !> Form operator 3 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine dpcm_original_point_op3_assemble(self, a, error)
      !> Operator
      class(dpcm_original_point_op3), intent(in) :: self
      !> Dense operator matrix
      complex(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp3(:, :), tmp4(:, :)
      complex(wp), allocatable :: tmp2(:, :)
      integer :: i

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp2(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp3(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp4(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_point_op3_assemble] allocation failed")
         return
      end if
      tmp1 = 0.0_wp
      do i = 1, self%npt
         tmp1(i, i) = self%c2(i)
      end do
      tmp2 = self%c1*tmp1
      tmp3 = transpose(self%c3)
      tmp4 = -tmp3
      a = tmp2 + tmp4
   end subroutine dpcm_original_point_op3_assemble

   !> Form operator 3 of the points idx alone
